import java.util.Locale;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int count = 0, sum = 0;
        int highest = -1, lowest = 101;
        String highName = "", lowName = "";
        int a = 0, b = 0, c = 0, d = 0, f = 0;

        while (in.hasNextLine()) {
            String line = in.nextLine();
            if (line.trim().isEmpty()) break;
            String text = line.trim();
            int space = text.indexOf(' ');
            String name = "";
            int score = -1;
            if (space > 0) {
                name = text.substring(0, space);
                String rest = text.substring(space).trim();
                if (!rest.contains(" ")) {
                    try {
                        score = Integer.parseInt(rest);
                    } catch (NumberFormatException e) {
                        score = -1;
                    }
                }
            }
            if (score < 0 || score > 100) {
                System.out.println("Skipping: " + line);
                continue;
            }
            char grade = score >= 90 ? 'A' : score >= 80 ? 'B' : score >= 70 ? 'C' : score >= 60 ? 'D' : 'F';
            switch (grade) {
                case 'A' -> a++;
                case 'B' -> b++;
                case 'C' -> c++;
                case 'D' -> d++;
                default -> f++;
            }
            System.out.printf("%-12s%3d  %c%n", name, score, grade);
            count++;
            sum += score;
            if (score > highest) { highest = score; highName = name; }
            if (score < lowest) { lowest = score; lowName = name; }
        }

        if (count == 0) {
            System.out.println("No students.");
        } else {
            System.out.println("Students: " + count);
            System.out.println(String.format(Locale.ROOT, "Average: %.2f", (double) sum / count));
            System.out.println("Highest: " + highName + " (" + highest + ")");
            System.out.println("Lowest: " + lowName + " (" + lowest + ")");
            System.out.printf("Grades: A=%d B=%d C=%d D=%d F=%d%n", a, b, c, d, f);
        }
    }
}
